describe('Login CAPTCHA after failed attempts', () => {
  const loginUrl = 'http://localhost:3000/login';
  const validUsername = 'testuser@example.com';
  const validPassword = 'ValidPassword123!';
  const invalidPassword = 'WrongPassword123!';

  beforeEach(() => {
    cy.visit(loginUrl);
    cy.clearCookies();
    cy.clearLocalStorage();
  });

  it('should display CAPTCHA after 3 failed login attempts', () => {
    // First failed attempt
    cy.get('input[name="email"]').type(validUsername);
    cy.get('input[name="password"]').type(invalidPassword);
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');
    cy.get('[data-testid="captcha-container"]').should('not.exist');

    // Second failed attempt
    cy.get('input[name="password"]').clear().type(invalidPassword);
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');
    cy.get('[data-testid="captcha-container"]').should('not.exist');

    // Third failed attempt - CAPTCHA should appear
    cy.get('input[name="password"]').clear().type(invalidPassword);
    cy.get('button[type="submit"]').click();
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');
    cy.get('[data-testid="captcha-container"]').should('be.visible');
    cy.get('[data-testid="captcha-iframe"]').should('exist');
    cy.get('button[type="submit"]').should('be.disabled');
  });

  it('should allow login after solving CAPTCHA on failed attempts', () => {
    // Perform 3 failed attempts to trigger CAPTCHA
    for (let i = 0; i < 3; i++) {
      cy.get('input[name="email"]').clear().type(validUsername);
      cy.get('input[name="password"]').clear().type(invalidPassword);
      cy.get('button[type="submit"]').click();
      cy.get('[data-testid="error-message"]').should('be.visible');
    }

    // Verify CAPTCHA is displayed
    cy.get('[data-testid="captcha-container"]').should('be.visible');
    cy.get('button[type="submit"]').should('be.disabled');

    // Mock CAPTCHA token response
    cy.window().then((win) => {
      win.grecaptchaCallback = cy.stub().returns('mock-captcha-token');
    });

    // Simulate CAPTCHA completion
    cy.get('[data-testid="captcha-checkbox"]').click();
    cy.get('[data-testid="captcha-token"]').should('have.value', 'mock-captcha-token');

    // Submit button should be enabled after CAPTCHA
    cy.get('button[type="submit"]').should('not.be.disabled');

    // Login with correct credentials
    cy.get('input[name="email"]').clear().type(validUsername);
    cy.get('input[name="password"]').clear().type(validPassword);
    cy.get('button[type="submit"]').click();

    // Verify successful login
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome');
  });

  it('should reset failed attempt counter after successful login', () => {
    // Perform 2 failed attempts
    for (let i = 0; i < 2; i++) {
      cy.get('input[name="email"]').clear().type(validUsername);
      cy.get('input[name="password"]').clear().type(invalidPassword);
      cy.get('button[type="submit"]').click();
      cy.get('[data-testid="error-message"]').should('be.visible');
    }

    // CAPTCHA should not be visible yet
    cy.get('[data-testid="captcha-container"]').should('not.exist');

    // Successful login
    cy.get('input[name="email"]').clear().type(validUsername);
    cy.get('input[name="password"]').clear().type(validPassword);
    cy.get('button[type="submit"]').click();
    cy.url().should('include', '/dashboard');

    // Logout
    cy.get('[data-testid="logout-button"]').click();
    cy.url().should('include', '/login');

    // Perform 3 failed attempts again - should trigger CAPTCHA
    for (let i = 0; i < 3; i++) {
      cy.get('input[name="email"]').clear().type(validUsername);
      cy.get('input[name="password"]').clear().type(invalidPassword);
      cy.get('button[type="submit"]').click();
      cy.get('[data-testid="error-message"]').should('be.visible');
    }

    // CAPTCHA should appear on third attempt
    cy.get('[data-testid="captcha-container"]').should('be.visible');
  });

  it('should handle CAPTCHA expiration and require re-verification', () => {
    // Trigger CAPTCHA with 3 failed attempts
    for (let i = 0; i < 3; i++) {
      cy.get('input[name="email"]').clear().type(validUsername);
      cy.get('input[name="password"]').clear().type(invalidPassword);
      cy.get('button[type="submit"]').click();
    }

    cy.get('[data-testid="captcha-container"]').should('be.visible');

    // Simulate CAPTCHA expiration
    cy.get('[data-testid="captcha-expired-message"]').should('not.exist');
    cy.wait(300000); // Wait for CAPTCHA to expire (5 minutes)
    cy.get('[data-testid="captcha-expired-message"]').should('be.visible');

    // CAPTCHA should be reset
    cy.get('[data-testid="captcha-token"]').should('have.value', '');
    cy.get('button[type="submit"]').should('be.disabled');
  });

  it('should prevent brute force attacks with rate limiting', () => {
    // Attempt multiple rapid failed logins
    for (let i = 0; i < 10; i++) {
      cy.get('input[name="email"]').clear().type(validUsername);
      cy.get('input[name="password"]').clear().type(invalidPassword);
      cy.get('button[type="submit"]').click();
      cy.get('[data-testid="error-message"]').should('be.visible');
    }

    // After excessive attempts, account should be temporarily locked
    cy.get('[data-testid="account-locked-message"]').should('be.visible');
    cy.get('button[type="submit"]').should('be.disabled');
    cy.get('[data-testid="lockout-timer"]').should('contain', 'Try again in');
  });
});
